{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_dist = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distances
    edges = []
    for u, v, d in distances:
        mreach = max(core_dist[u], core_dist[v], d)
        edges.append((u, v, mreach))

    # Kruskal's MST on mutual reachability graph
    edges.sort(key=lambda e: e[2])

    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w

    return {"mst_edges": mst_edges, "total_weight": total_weight}
